#[must_use]
pub fn get_loot_property_type(block: &str, name: &str) -> Option<&'static LootPropertyType> {
    LOOT_PROPERTY_TYPES
        .binary_search_by_key(&(block, name), |(key, _)| *key)
        .ok()
        .map(|index| &LOOT_PROPERTY_TYPES[index].1)
}
