#[must_use]
pub fn get_loot_table(key: &str) -> Option<&'static LootTable> {
    LOOT_TABLES_BY_KEY
        .binary_search_by_key(&key, |&(k, _)| k)
        .ok()
        .map(|i| LOOT_TABLES_BY_KEY[i].1)
}
#[must_use]
pub fn get_chest_loot_table(key: &str) -> Option<&'static LootTable> {
    get_loot_table(key)
}
